// Map the classified intent to a brokerage-approved disqualification reason code
// (SOP Section 34 Appendix reason codes)
const item = $input.first().json;
const REASON_CODE_BY_INTENT = {
  renter_not_buyer: 'RENTER_NOT_BUYER',
  just_browsing: 'JUST_BROWSING_LOW_INTENT',
  unresponsive: 'UNRESPONSIVE_3_ATTEMPTS'
};
const reasonCode = item.needs_human_review
  ? 'NEEDS_HUMAN_REVIEW'
  : (REASON_CODE_BY_INTENT[item.intent] || 'BUDGET_BELOW_INVENTORY_FLOOR');

return [{
  json: {
    ...item,
    disqualification_reason_code: reasonCode,
    scheduled_for: new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)
  }
}];

